/* eslint-disable */
/**
 * 内置音源脚本集合。
 *
 * 每个脚本的内容必须与源文件逐字节一致，所以用 JSON 字符串分段拼接：
 * 直接写模板字符串会被脚本里的反引号、反斜杠和 ${} 打断；
 * 用 base64 又要额外依赖运行时解码器。JSON 转义由生成脚本保证正确性。
 *
 * 不要手工编辑本文件 —— 需要换源时重新生成。
 */

export interface BuiltinSourceEntry {
  /** 脚本头里的 @name，用于在已安装列表里认出「自己人」 */
  name: string
  /** 脚本头里的 @version */
  version: string
  /** 脚本原文 */
  script: string
}

